style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
/* Background Image */
    body {
        background: url('https://i.imgur.com/https://i.pinimg.com/originals/a1/fb/90/a1fb90dbf9725338b89689148c47ecd4.gif.jpg') no-repeat center center fixed;
        background-size: cover !important;
    }
    
    /* Make Background Visible */
    ytd-app {
        background: transparent !important;
    }
    
    /* Customize Sidebar & Header */
    #guide-content, ytd-mini-guide-renderer, ytd-masthead {
        background: rgba(0, 128, 0, 0.8) !important; /* Green Jupiter Theme */
    }
    
    /* Text Color Tweaks */
    ytd-guide-entry-renderer a,
    ytd-guide-section-renderer {
        color: white !important;
    }
    
    /* Video Title Colors */
    h1.title yt-formatted-string,
    h3.ytd-video-primary-info-renderer {
        color: #ffcc00 !important; /* Golden Accents */
    }
}
